contract InvMutTest {
    C c;
    address owner;
    constructor(C _c) { c = _c; owner = address(this); }

    // We will attempt to call createGameItem with parameters and check the observable effects.
    // Note: createGameItem requires isAdmin[msg.sender] == true. The freshly deployed C in the checker
    // sets isAdmin[_ownerAddress]=true where _ownerAddress was the constructor arg used when deploying C.
    // The checker deploys a fresh C and then deploys this test passing that C; per harness, msg.sender for c calls
    // will be this contract, which is not guaranteed to be the original owner. Therefore we must first mark
    // this contract as admin by calling adjustAdminAccess from the original owner. But we cannot call as that owner.
    // Instead we will exploit that the checker deploys C with some owner address; we cannot assume it's this contract.
    // To make a general property that does not require being admin, we will first read uniqueTokensOutstanding(),
    // then try to call createGameItem and capture whether it reverted. If it succeeded, then uniqueTokensOutstanding
    // must increase by 1 and the uri for the new id must equal the provided tokenURI. If it reverted, uniqueTokensOutstanding
    // must remain unchanged.

    function run(string calldata name_, string calldata tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public payable {
        // No precondition on inputs
        uint256 beforeCount = c.uniqueTokensOutstanding();

        bool reverted;
        // createGameItem is a public function that mutates state; call it top-level and catch revert
        try c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterCount = c.uniqueTokensOutstanding();

        // If the call reverted, the token count must be unchanged. If it succeeded, the count increments by 1 and
        // the uri of the new token id (beforeCount) equals the provided tokenURI (or if tokenURI empty, then fallback to base URI from ERC1155)
        // We can observe uri(...) via the public function.
        string memory gotURI;
        // Only call uri for the new id when non-reverted and afterCount > beforeCount to avoid calling out-of-range ids.
        if (!reverted) {
            // afterCount should be beforeCount + 1
            // read uri for the newly created token id which is index beforeCount
            gotURI = c.uri(beforeCount);
        }

        // Build the assert: (reverted ==> afterCount == beforeCount) && (!reverted ==> afterCount == beforeCount + 1 && (keccak256(bytes(gotURI)) == keccak256(bytes(tokenURI)) || (bytes(tokenURI).length == 0 && keccak256(bytes(gotURI)) == keccak256(bytes(c.uri(beforeCount))))))
        // Note: double call to c.uri(beforeCount) inside assert is allowed (view). But avoid complex OR; simplify: if not reverted then afterCount==beforeCount+1 and keccak256(gotURI)==keccak256(tokenURI).

        // Use abi.encodePacked/keccak256 to compare strings inside assert
        if (reverted) {
            assert(afterCount == beforeCount);
        } else {
            // when succeeded
            bytes32 hGot = keccak256(bytes(gotURI));
            bytes32 hProvided = keccak256(bytes(tokenURI));
            assert(afterCount == beforeCount + 1 && hGot == hProvided);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function driving the property test
    function run(string calldata name_, string calldata tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public payable {
        uint256 beforeCount = c.uniqueTokensOutstanding();

        bool reverted;
        // state-changing call must be a top-level statement; use try/catch to observe revert
        try c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterCount = c.uniqueTokensOutstanding();
        string memory newURI = "";
        if (!reverted) {
            // when call succeeded, the new token id is beforeCount
            newURI = c.uri(beforeCount);
        }

        // Exactly one assert stating the general invariant:
        // If reverted then count unchanged. If not reverted then count == before+1 and uri(beforeCount) == tokenURI
        bytes32 hNew = keccak256(bytes(newURI));
        bytes32 hProvided = keccak256(bytes(tokenURI));
        assert((reverted && afterCount == beforeCount) || (!reverted && afterCount == beforeCount + 1 && hNew == hProvided));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function driving the property test
    function run(string calldata name_, string calldata tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public payable {
        // bound lengths to avoid extreme gas or storage effects
        require(bytes(name_).length < 200);
        require(bytes(tokenURI).length < 200);
        // read observable before-state
        uint256 before = c.uniqueTokensOutstanding();

        bool reverted;
        // perform the state-changing call as a top-level statement and observe revert
        try c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = c.uniqueTokensOutstanding();

        // Single assert: either reverted and count unchanged, or succeeded and increased by exactly 1
        assert((reverted && after == before) || (!reverted && after == before + 1));
    }

    receive() external payable {}
}
